package expo.modules.kotlin.objects

import expo.modules.kotlin.jni.ExpectedType
import expo.modules.kotlin.jni.JNIFunctionBody
import expo.modules.kotlin.jni.decorators.JSDecoratorsBridgingObject
import expo.modules.kotlin.types.JSTypeConverter

class ConstantComponent(
  /**
   * Name of the constant.
   */
  val name: String,

  /**
   * Synchronous function that is called when the constant is being accessed for the first time.
   */
  val getter: () -> Any?
) {
  /**
   * Attaches constant to the provided js object.
   * Uses registerProperty with only a getter to simulate a read-only constant.
   */
  fun attachToJSObject(jsObject: JSDecoratorsBridgingObject) {
    val jniGetter = JNIFunctionBody { _ ->
      val result = getter.invoke()
      return@JNIFunctionBody JSTypeConverter.convertToJSValue(result)
    }

    // Register as a read-only property (getter only, no setter)
    jsObject.registerProperty(
      name,
      false, // getterTakesOwner
      emptyArray<ExpectedType>(), // getterExpectedType
      jniGetter,
      false, // setterTakesOwner
      emptyArray<ExpectedType>(), // setterExpectedType
      null // setter (null = read-only)
    )
  }
}
